// shared 形态（message.send payload、各层透传用，不带 type）
// 已存在于 shared/protocol.ts:199（前一 slice 落地）
type SharedImage = { data: string; mimeType: string }

// pi 形态（仅 rpc-client 内部组装，infra/pi/pi-protocol.ts:331）
interface PiImageContentBlock { type: 'image'; data: string; mimeType: string }

// rpc-client.prompt 内部转换（唯一组装点）
const piImages = images && images.length > 0
  ? images.map(i => ({ type: 'image' as const, data: i.data, mimeType: i.mimeType }))
  : undefined
const params: Record<string, unknown> = { message: content }
if (piImages) params.images = piImages
return this.sendCommand('prompt', params)
